package com.uniquebattery;

final class Battery
{
	static final double FULL = 100;
	private static final double TICKS_PER_MINUTE = 100;

	private Battery()
	{
	}

	static double drain(double charge, int pointsPerMinute)
	{
		return clamp(charge - pointsPerMinute / TICKS_PER_MINUTE);
	}

	static double refill(double charge, double denominator, long value, int rarityStrength, int valueStrength)
	{
		double rarityPoints = Math.min(50, 8 * Math.log10(denominator));
		double valuePoints = Math.min(50, 5 * Math.log10(1 + Math.max(0, value) / 1_000.0));
		return clamp(charge + rarityPoints * rarityStrength / 100 + valuePoints * valueStrength / 100);
	}

	static double clamp(double charge)
	{
		return Double.isFinite(charge) ? Math.max(0, Math.min(FULL, charge)) : FULL;
	}
}

package com.uniquebattery;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

final class BossingLadder
{
	enum Tier
	{
		EASY, MEDIUM, HARD, ELITE, MASTER, GRANDMASTER
	}

	// OSRS Wiki, Guide:Bossing Ladder, revision 15408640. Names here match RuneLite NPC names.
	// https://oldschool.runescape.wiki/w/Guide:Bossing_Ladder?oldid=15408640
	private static final Map<String, Tier> NPC_TIERS = npcTiers();

	private BossingLadder()
	{
	}

	static Tier npcTier(String npcName, boolean soloGodWars)
	{
		if (npcName == null)
		{
			return null;
		}
		String name = npcName.toLowerCase(Locale.ROOT);
		if (soloGodWars)
		{
			switch (name)
			{
				case "commander zilyana":
				case "k'ril tsutsaroth":
					return Tier.HARD;
				case "kree'arra":
				case "general graardor":
					return Tier.ELITE;
				default:
					break;
			}
		}
		return NPC_TIERS.get(name);
	}

	static boolean isGodWarsGeneral(String name)
	{
		return name != null && npcTier(name, true) != npcTier(name, false);
	}

	static Tier tombsTier(int raidLevel)
	{
		if (raidLevel >= 500)
		{
			return Tier.GRANDMASTER;
		}
		// The ladder starts at 300. Use Elite for lower-invocation runs.
		return raidLevel >= 300 ? Tier.MASTER : Tier.ELITE;
	}

	private static Map<String, Tier> npcTiers()
	{
		Map<String, Tier> tiers = new HashMap<>();
		add(tiers, Tier.EASY, "Brutus|Wintertodt|Tempoross|Obor|Bryophyta|Deranged archaeologist|Scurrius"
			+ "|Ahrim the Blighted|Dharok the Wretched|Guthan the Infested|Karil the Tainted|Torag the Corrupted|Verac the Defiled");
		add(tiers, Tier.MEDIUM, "Shellbane Gryphon|Penance Queen|Amoxliatl|The Hueycoatl|Hespori|Giant Mole"
			+ "|Crazy archaeologist|Chaos Fanatic|Kraken|Sarachnis|King Black Dragon|Zalcano|Thermonuclear smoke devil"
			+ "|The Mimic|Branda the Fire Queen|Eldric the Ice King|Blood Moon|Blue Moon|Eclipse Moon|Mad Angel"
			+ "|Commander Zilyana|K'ril Tsutsaroth|Kree'arra|General Graardor");
		add(tiers, Tier.HARD, "Scorpia|Chaos Elemental|Vet'ion|Calvar'ion|Venenatis|Spindel|Callisto|Artio"
			+ "|Dagannoth Prime|Dagannoth Rex|Dagannoth Supreme|Dawn|Dusk|Skotizo|TzTok-Jad|Demonic gorilla"
			+ "|Tormented Demon|Crystalline Hunllef|Abyssal Sire|Cerberus|Araxxor|Alchemical Hydra|Corporeal Beast|Kalphite Queen");
		add(tiers, Tier.ELITE, "Zulrah|Vorkath|Phantom Muspah|Duke Sucellus|Maggot King|Corrupted Hunllef"
			+ "|The Whisperer|The Leviathan|Vardorvis|Nex|Yama");
		add(tiers, Tier.MASTER, "The Nightmare|Nightmare|Phosani's Nightmare|Demonic Brutus|Doom of Mokhaiotl|Sol Heredit|TzKal-Zuk");
		return Map.copyOf(tiers);
	}

	private static void add(Map<String, Tier> tiers, Tier tier, String names)
	{
		for (String name : names.split("\\|"))
		{
			tiers.put(name.toLowerCase(Locale.ROOT), tier);
		}
	}
}

package com.uniquebattery;

import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarbitID;

import static com.uniquebattery.BossingLadder.Tier.*;

final class EncounterDetector
{
	private static final int WINTERTODT_REGION = 6461;
	private static final int TEMPOROSS_REGION = 12588;
	private static final int FIGHT_CAVES_REGION = 9551;
	private static final int INFERNO_REGION = 9043;
	private static final int CORRUPTED_GAUNTLET_REGION = 7768;

	private static final Set<Integer> HARD_THEATRE_NPCS = Set.of(
		NpcID.TOB_MAIDEN_100_HARD, NpcID.TOB_MAIDEN_70_HARD, NpcID.TOB_MAIDEN_50_HARD, NpcID.TOB_MAIDEN_30_HARD,
		NpcID.TOB_BLOAT_HARD, NpcID.NYLOCAS_BOSS_MELEE_HARD, NpcID.NYLOCAS_BOSS_MAGIC_HARD, NpcID.NYLOCAS_BOSS_RANGED_HARD,
		NpcID.TOB_SOTETSEG_COMBAT_HARD, NpcID.TOB_XARPUS_COMBAT_HARD,
		NpcID.VERZIK_PHASE1_HARD, NpcID.VERZIK_PHASE2_HARD, NpcID.VERZIK_PHASE3_HARD);

	private final Client client;
	private boolean hardTheatre;

	@Inject
	EncounterDetector(Client client)
	{
		this.client = client;
	}

	BossingLadder.Tier tier(Player player)
	{
		Actor target = player.getInteracting();
		NPC npc = target instanceof NPC ? (NPC) target : null;
		WorldView world = client.getTopLevelWorldView();
		boolean instanced = world.isInstance();

		BossingLadder.Tier raidTier = raidTier(instanced, npc);
		if (raidTier != null)
		{
			return raidTier;
		}

		int region = WorldPoint.fromLocalInstance(world.getScene(), player.getLocalLocation(), world.getPlane()).getRegionID();
		BossingLadder.Tier areaTier = areaTier(instanced, region);
		if (areaTier != null)
		{
			return areaTier;
		}
		if (npc == null)
		{
			return null;
		}

		String name = npc.getName();
		if ("Yama".equalsIgnoreCase(name) && client.getVarbitValue(VarbitID.YAMA_IMP_CONTRACT_SIGNED) > 0)
		{
			return GRANDMASTER;
		}
		boolean soloGodWars = instanced && BossingLadder.isGodWarsGeneral(name) && isOnlyPlayer(world, player);
		return BossingLadder.npcTier(name, soloGodWars);
	}

	void reset()
	{
		hardTheatre = false;
	}

	private BossingLadder.Tier raidTier(boolean instanced, NPC npc)
	{
		if (instanced && client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS) == 2)
		{
			hardTheatre |= npc != null && HARD_THEATRE_NPCS.contains(npc.getId());
			return hardTheatre ? GRANDMASTER : MASTER;
		}
		hardTheatre = false;
		if (client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1)
		{
			return client.getVarbitValue(VarbitID.RAIDS_CHALLENGE_MODE) == 1 ? GRANDMASTER : MASTER;
		}
		if (instanced && client.getVarbitValue(VarbitID.TOA_CLIENT_PARTYSTATUS) == 2)
		{
			return BossingLadder.tombsTier(client.getVarbitValue(VarbitID.TOA_CLIENT_RAID_LEVEL));
		}
		if (instanced && client.getVarbitValue(VarbitID.TFA_CLIENT_PARTYSTATUS) == 2)
		{
			return MASTER;
		}
		return null;
	}

	private BossingLadder.Tier areaTier(boolean instanced, int region)
	{
		if (region == WINTERTODT_REGION || region == TEMPOROSS_REGION)
		{
			return EASY;
		}
		if (!instanced)
		{
			return null;
		}
		if (client.getVarbitValue(VarbitID.PLAYER_IN_GAUNTLET) == 1)
		{
			return region == CORRUPTED_GAUNTLET_REGION ? ELITE : HARD;
		}
		if (client.getVarbitValue(VarbitID.BARBASSAULT_AREAEXIT_PENDING) == 1)
		{
			return MEDIUM;
		}
		if (region == FIGHT_CAVES_REGION)
		{
			return HARD;
		}
		return region == INFERNO_REGION ? MASTER : null;
	}

	private static boolean isOnlyPlayer(WorldView world, Player player)
	{
		for (Player other : world.players())
		{
			if (other != player)
			{
				return false;
			}
		}
		return true;
	}
}

