package com.uniquebattery;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import javax.swing.JProgressBar;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

final class UniqueBatteryPanel extends PluginPanel
{
	private static final Color HIGH = new Color(85, 171, 111);
	private static final Color MEDIUM = new Color(210, 154, 67);
	private static final Color LOW = new Color(202, 95, 89);
	private final JProgressBar meter = new BatteryMeter();
	private volatile int currentPercent = -1;
	private volatile boolean active;
	private int displayedPercent = -1;

	UniqueBatteryPanel()
	{
		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(16, 10, 12, 10));
		meter.getAccessibleContext().setAccessibleName("Unique Battery charge");
		add(meter, BorderLayout.NORTH);
	}

	void showCharge(int percent)
	{
		if (currentPercent == percent)
		{
			return;
		}
		currentPercent = percent;
		if (active)
		{
			SwingUtilities.invokeLater(this::refreshMeter);
		}
	}

	@Override
	public void onActivate()
	{
		active = true;
		refreshMeter();
	}

	@Override
	public void onDeactivate()
	{
		active = false;
	}

	private void refreshMeter()
	{
		int percent = currentPercent;
		if (active && displayedPercent != percent)
		{
			meter.setValue(Math.max(0, percent));
			meter.setString(percent < 0 ? "Log in to view" : percent + "%");
			displayedPercent = percent;
		}
	}

	private static final class BatteryMeter extends JProgressBar
	{
		private static final int WIDTH = 90;
		private static final int HEIGHT = 182;
		private static final int CASE_X = 9;
		private static final int CASE_WIDTH = WIDTH - 2 * CASE_X;
		private static final int CASE_HEIGHT = 140;
		private static final Color CASE_EDGE = new Color(163, 173, 178);
		private static final Color INTERIOR = new Color(23, 28, 31);
		private static final Color LABEL = new Color(237, 241, 242);
		private static final Color EMPTY_BOLT = new Color(223, 173, 76);
		private static final Path2D BOLT = createBolt();

		private BatteryMeter()
		{
			super(0, 100);
			setPreferredSize(new Dimension(WIDTH, HEIGHT));
			setOpaque(false);
			setBorderPainted(false);
			setStringPainted(true);
			setString("Log in to view");
		}

		@Override
		protected void paintComponent(Graphics original)
		{
			Graphics2D graphics = (Graphics2D) original.create();
			try
			{
				graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
				double scale = Math.min(1.0, getWidth() / (double) WIDTH);
				graphics.translate((getWidth() - WIDTH * scale) / 2, (getHeight() - HEIGHT * scale) / 2);
				graphics.scale(scale, scale);

				graphics.setColor(CASE_EDGE);
				graphics.fillRoundRect(31, 1, 28, 15, 9, 9);
				graphics.fillRoundRect(CASE_X, 11, CASE_WIDTH, CASE_HEIGHT, 16, 16);

				paintCharge(graphics, getValue());
				paintLabel(graphics, getString());
			}
			finally
			{
				graphics.dispose();
			}
		}

		private void paintCharge(Graphics2D graphics, int percent)
		{
			final int x = CASE_X + 3;
			final int y = 14;
			final int width = CASE_WIDTH - 6;
			final int height = CASE_HEIGHT - 6;
			RoundRectangle2D interior = new RoundRectangle2D.Float(x, y, width, height, 11, 11);
			graphics.setColor(INTERIOR);
			graphics.fill(interior);
			if (percent == 0)
			{
				graphics.setColor(EMPTY_BOLT);
				graphics.fill(BOLT);
				return;
			}

			Color chargeColor = percent <= 20 ? LOW : percent <= 50 ? MEDIUM : HIGH;
			int fillHeight = (int) Math.ceil(height * percent / 100.0);
			Graphics2D fill = (Graphics2D) graphics.create();
			try
			{
				fill.clip(interior);
				fill.setPaint(new GradientPaint(x, y, chargeColor.brighter(), x + width, y, chargeColor.darker()));
				fill.fillRect(x, y + height - fillHeight, width, fillHeight);
			}
			finally
			{
				fill.dispose();
			}
		}

		private void paintLabel(Graphics2D graphics, String label)
		{
			boolean signedIn = label.endsWith("%");
			graphics.setFont(getFont().deriveFont(Font.BOLD, signedIn ? 20f : 14f));
			FontMetrics metrics = graphics.getFontMetrics();
			int x = (WIDTH - metrics.stringWidth(label)) / 2;
			int baseline = signedIn ? 88 : 174;
			if (signedIn)
			{
				graphics.setColor(INTERIOR);
				graphics.drawString(label, x, baseline + 1);
			}
			graphics.setColor(LABEL);
			graphics.drawString(label, x, baseline);
		}

		private static Path2D createBolt()
		{
			Path2D bolt = new Path2D.Float();
			bolt.moveTo(49, 100);
			bolt.lineTo(35, 118);
			bolt.lineTo(44, 118);
			bolt.lineTo(41, 132);
			bolt.lineTo(55, 113);
			bolt.lineTo(46, 113);
			bolt.closePath();
			return bolt;
		}
	}

	static BufferedImage icon()
	{
		BufferedImage image = new BufferedImage(18, 18, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setColor(new Color(225, 229, 225));
			graphics.drawRoundRect(1, 4, 13, 9, 2, 2);
			graphics.fillRect(15, 7, 2, 4);
			graphics.setColor(HIGH);
			graphics.fillRect(3, 6, 8, 6);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}
}

package com.uniquebattery;

import com.google.inject.Provides;
import java.util.EnumMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.http.api.loottracker.LootRecordType;

@PluginDescriptor(
	name = "Unique Battery",
	description = "A side-panel battery charged by unique drops and drained by play.",
	tags = {"loot", "unique", "battery", "pvm"}
)
public final class UniqueBatteryPlugin extends Plugin
{
	private static final String CHARGE_KEY = "charge";
	private static final int SAVE_INTERVAL_TICKS = 50;
	private static final int IDLE_CLIENT_TICKS = 3_000;
	private static final int SKILLING_WINDOW_TICKS = 34;
	private static final Set<Skill> COMBAT_SKILLS = Set.of(
		Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.HITPOINTS, Skill.RANGED, Skill.MAGIC, Skill.PRAYER
	);

	@Inject private Client client;
	@Inject private ClientToolbar toolbar;
	@Inject private ConfigManager configManager;
	@Inject private UniqueBatteryConfig config;
	@Inject private ItemManager itemManager;
	@Inject private EncounterDetector encounters;

	private final Map<Skill, Integer> skillXp = new EnumMap<>(Skill.class);
	private NavigationButton navigation;
	private UniqueBatteryPanel panel;
	private Map<String, Map<String, Double>> uniqueDrops = Map.of();
	private final int[] encounterDrain = new int[BossingLadder.Tier.values().length];
	private int regularDrain;
	private int skillingDrain;
	private int rarityRefill;
	private int valueRefill;
	private boolean drainEnabled;
	private String profileKey;
	private double charge = Battery.FULL;
	private boolean dirty;
	private int ticksSinceSave;
	private int skillingTicks;

	@Provides
	UniqueBatteryConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(UniqueBatteryConfig.class);
	}

	@Override
	protected synchronized void startUp()
	{
		readSettings();
		uniqueDrops = UniqueDrops.withOverrides(config.customUniques());
		panel = new UniqueBatteryPanel();
		navigation = NavigationButton.builder()
			.tooltip("Unique Battery")
			.icon(UniqueBatteryPanel.icon())
			.priority(20)
			.panel(panel)
			.build();
		toolbar.addNavigation(navigation);
	}

	@Override
	protected synchronized void shutDown()
	{
		saveCharge();
		profileKey = null;
		resetActivity();
		toolbar.removeNavigation(navigation);
		navigation = null;
		panel = null;
	}

	@Subscribe
	public synchronized void onConfigChanged(ConfigChanged event)
	{
		if (!UniqueBatteryConfig.GROUP.equals(event.getGroup()) || CHARGE_KEY.equals(event.getKey()))
		{
			return;
		}
		if ("customUniques".equals(event.getKey()))
		{
			uniqueDrops = UniqueDrops.withOverrides(config.customUniques());
		}
		else
		{
			readSettings();
		}
	}

	@Subscribe
	public synchronized void onProfileChanged(ProfileChanged event)
	{
		readSettings();
		uniqueDrops = UniqueDrops.withOverrides(config.customUniques());
	}

	@Subscribe
	public synchronized void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.LOGIN_SCREEN_AUTHENTICATOR)
		{
			saveCharge();
			profileKey = null;
			resetActivity();
			updateMeter();
		}
	}

	@Subscribe
	public synchronized void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();
		if (client.getGameState() != GameState.LOGGED_IN || player == null || !loadProfile())
		{
			return;
		}

		if (drainEnabled && charge > 0 && (skillingTicks > 0
			|| client.getMouseIdleTicks() < IDLE_CLIENT_TICKS || client.getKeyboardIdleTicks() < IDLE_CLIENT_TICKS))
		{
			setCharge(Battery.drain(charge, drainRate(player)));
		}
		if (skillingTicks > 0)
		{
			--skillingTicks;
		}
		if (dirty && ++ticksSinceSave >= SAVE_INTERVAL_TICKS)
		{
			saveCharge();
		}
	}

	@Subscribe
	public synchronized void onStatChanged(StatChanged event)
	{
		if (COMBAT_SKILLS.contains(event.getSkill()) || client.getGameState() != GameState.LOGGED_IN || !loadProfile())
		{
			return;
		}
		Integer previous = skillXp.put(event.getSkill(), event.getXp());
		if (previous != null && event.getXp() > previous)
		{
			skillingTicks = SKILLING_WINDOW_TICKS;
		}
	}

	@Subscribe
	public synchronized void onLootReceived(LootReceived event)
	{
		if ((rarityRefill == 0 && valueRefill == 0) || client.getGameState() != GameState.LOGGED_IN
			|| (event.getType() != LootRecordType.NPC && event.getType() != LootRecordType.EVENT))
		{
			return;
		}

		Map<String, Double> sourceDrops = UniqueDrops.forSource(uniqueDrops, event.getName());
		if (sourceDrops.isEmpty() || !loadProfile() || charge >= Battery.FULL)
		{
			return;
		}
		double restored = charge;
		for (ItemStack stack : event.getItems())
		{
			long quantity = stack.getQuantity();
			if (quantity <= 0)
			{
				continue;
			}
			int id = itemManager.canonicalize(stack.getId());
			String item = itemManager.getItemComposition(id).getName();
			double denominator = UniqueDrops.denominator(sourceDrops, item);
			if (denominator > 1)
			{
				long unitPrice = valueRefill == 0 ? 0 : itemManager.getItemPrice(id);
				long value = unitPrice > Long.MAX_VALUE / quantity ? Long.MAX_VALUE : unitPrice * quantity;
				restored = Battery.refill(restored, denominator, value, rarityRefill, valueRefill);
				if (restored >= Battery.FULL)
				{
					break;
				}
			}
		}
		if (charge != restored)
		{
			setCharge(restored);
			saveCharge();
		}
	}

	private int drainRate(Player player)
	{
		BossingLadder.Tier tier = encounters.tier(player);
		return tier != null ? encounterDrain[tier.ordinal()] : skillingTicks > 0 ? skillingDrain : regularDrain;
	}

	private void readSettings()
	{
		regularDrain = config.regularDrain();
		skillingDrain = config.skillingDrain();
		encounterDrain[BossingLadder.Tier.EASY.ordinal()] = config.easyDrain();
		encounterDrain[BossingLadder.Tier.MEDIUM.ordinal()] = config.mediumDrain();
		encounterDrain[BossingLadder.Tier.HARD.ordinal()] = config.hardDrain();
		encounterDrain[BossingLadder.Tier.ELITE.ordinal()] = config.eliteDrain();
		encounterDrain[BossingLadder.Tier.MASTER.ordinal()] = config.masterDrain();
		encounterDrain[BossingLadder.Tier.GRANDMASTER.ordinal()] = config.grandmasterDrain();
		rarityRefill = config.rarityRefill();
		valueRefill = config.valueRefill();
		drainEnabled = regularDrain != 0 || skillingDrain != 0;
		for (int rate : encounterDrain)
		{
			drainEnabled |= rate != 0;
		}
	}

	private boolean loadProfile()
	{
		String currentKey = configManager.getRSProfileKey();
		if (currentKey == null)
		{
			return false;
		}
		if (!currentKey.equals(profileKey))
		{
			saveCharge();
			profileKey = currentKey;
			resetActivity();
			for (Skill skill : Skill.values())
			{
				skillXp.put(skill, client.getSkillExperience(skill));
			}
			Double saved = configManager.getConfiguration(UniqueBatteryConfig.GROUP, profileKey, CHARGE_KEY, Double.class);
			charge = saved == null ? Battery.FULL : Battery.clamp(saved);
			updateMeter();
		}
		return true;
	}

	private void resetActivity()
	{
		skillXp.clear();
		skillingTicks = 0;
		encounters.reset();
	}

	private void setCharge(double updated)
	{
		if (charge != updated)
		{
			charge = updated;
			dirty = true;
			updateMeter();
		}
	}

	private void saveCharge()
	{
		if (dirty && profileKey != null)
		{
			dirty = false;
			configManager.setConfiguration(UniqueBatteryConfig.GROUP, profileKey, CHARGE_KEY, charge);
		}
		ticksSinceSave = 0;
	}

	private void updateMeter()
	{
		if (panel != null)
		{
			panel.showCharge(profileKey == null ? -1 : (int) Math.ceil(charge));
		}
	}
}

package com.uniquebattery;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

final class UniqueDrops
{
	private static final Map<String, Map<String, Double>> BUILT_IN = builtIn();

	private UniqueDrops()
	{
	}

	static Map<String, Double> forSource(Map<String, Map<String, Double>> drops, String source)
	{
		return drops.getOrDefault(normalize(source), Map.of());
	}

	static double denominator(Map<String, Double> sourceDrops, String item)
	{
		return sourceDrops.getOrDefault(normalize(item), 0.0);
	}

	static Map<String, Map<String, Double>> withOverrides(String rules)
	{
		if (rules.isBlank())
		{
			return BUILT_IN;
		}
		Map<String, Map<String, Double>> overrides = new HashMap<>();
		for (String rule : rules.split(";"))
		{
			String[] fields = rule.split("\\|", -1);
			if (fields.length != 3 || fields[0].isBlank() || fields[1].isBlank())
			{
				continue;
			}
			try
			{
				double denominator = Double.parseDouble(fields[2].trim());
				if (Double.isFinite(denominator) && denominator > 1)
				{
					String source = normalize(fields[0]);
					overrides.computeIfAbsent(source, key -> new HashMap<>(BUILT_IN.getOrDefault(key, Map.of())))
						.put(normalize(fields[1]), denominator);
				}
			}
			catch (NumberFormatException ignored)
			{
				// Individual malformed entries leave the rest of the rules usable.
			}
		}
		Map<String, Map<String, Double>> combined = new HashMap<>(BUILT_IN);
		overrides.forEach((source, items) -> combined.put(source, Map.copyOf(items)));
		return Map.copyOf(combined);
	}

	private static String normalize(String name)
	{
		return name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
	}

	private static Map<String, Map<String, Double>> builtIn()
	{
		Map<String, Map<String, Double>> drops = new HashMap<>();
		add(drops, "Zulrah", 512, "Tanzanite fang|Magic fang|Serpentine visage|Uncut onyx");
		add(drops, "Zulrah", 3_000, "Pet snakeling|Jar of swamp");
		add(drops, "Zulrah", 6_554, "Tanzanite mutagen|Magma mutagen");
		add(drops, "Vorkath", 5_000, "Draconic visage|Skeletal visage");
		add(drops, "Vorkath", 3_000, "Vorki|Jar of decay");
		add(drops, "Kraken", 512, "Trident of the seas (full)");
		add(drops, "Kraken", 400, "Kraken tentacle");
		add(drops, "Kraken", 3_000, "Pet kraken");
		add(drops, "Kraken", 1_000, "Jar of dirt");
		add(drops, "Abyssal demon", 512, "Abyssal whip");
		add(drops, "K'ril Tsutsaroth", 127, "Zamorakian spear");
		add(drops, "General Graardor", 381, "Bandos chestplate|Bandos tassets|Bandos boots");
		add(drops, "Commander Zilyana", 508, "Armadyl crossbow|Saradomin's light");
		add(drops, "Kree'arra", 381, "Armadyl helmet|Armadyl chestplate|Armadyl chainskirt");

		add(drops, "Reward cart (Wintertodt)", 1_000, "Tome of fire (empty)|Tome of fire");
		add(drops, "Reward cart (Wintertodt)", 10_000, "Dragon axe");
		add(drops, "Reward pool (Tempoross)", 400, "Fish barrel|Fish barrel (closed)|Tackle box");
		add(drops, "Reward pool (Tempoross)", 1_600, "Tome of water (empty)|Big harpoonfish");
		add(drops, "Reward pool (Tempoross)", 8_000, "Dragon harpoon");

		// Reference odds for scoring raid rewards. Actual odds depend on the run.
		add(drops, "Chambers of Xeric", 345, "Twisted bow|Kodai insignia|Elder maul");
		add(drops, "Chambers of Xeric", 86.25, "Dragon claws|Ancestral hat|Ancestral robe top|Ancestral robe bottom");
		add(drops, "Chambers of Xeric", 57.5, "Twisted buckler|Dragon hunter crossbow|Dinh's bulwark");
		add(drops, "Chambers of Xeric", 17.25, "Dexterous prayer scroll|Arcane prayer scroll");
		add(drops, "Theatre of Blood", 171, "Scythe of vitur (uncharged)");
		add(drops, "Theatre of Blood", 57, "Ghrazi rapier|Sanguinesti staff (uncharged)|Justiciar faceguard|Justiciar chestguard|Justiciar legguards");
		add(drops, "Theatre of Blood", 21.375, "Avernic defender hilt");
		add(drops, "Tombs of Amascut", 480, "Tumeken's shadow (uncharged)");
		add(drops, "Tombs of Amascut", 160, "Masori mask|Masori body|Masori chaps");
		add(drops, "Tombs of Amascut", 120, "Elidinis' ward");
		add(drops, "Tombs of Amascut", 68.57, "Osmumten's fang|Lightbearer");
		drops.replaceAll((source, items) -> Map.copyOf(items));
		return Map.copyOf(drops);
	}

	private static void add(Map<String, Map<String, Double>> drops, String source, double denominator, String items)
	{
		Map<String, Double> sourceDrops = drops.computeIfAbsent(normalize(source), key -> new HashMap<>());
		for (String item : items.split("\\|"))
		{
			sourceDrops.put(normalize(item), denominator);
		}
	}
}

package com.uniquebattery;

import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class BatteryTest
{
	@Test
	public void drainsAtTheConfiguredPerMinuteRate()
	{
		double charge = 100;
		for (int tick = 0; tick < 100; tick++)
		{
			charge = Battery.drain(charge, 5);
		}
		assertEquals(95, charge, 1e-9);
		assertEquals(0, Battery.drain(0.01, 5), 0);
		assertEquals(50, Battery.drain(50, 0), 0);
	}

	@Test
	public void rarerAndMoreValuableDropsRestoreMoreCharge()
	{
		double baseline = Battery.refill(0, 100, 10_000, 100, 100);
		assertTrue(Battery.refill(0, 1_000, 10_000, 100, 100) > baseline);
		assertTrue(Battery.refill(0, 100, 100_000, 100, 100) > baseline);
		assertEquals(0, Battery.refill(0, 100, 10_000, 0, 0), 0);
		assertEquals(24, Battery.refill(0, 1_000, 0, 100, 100), 0);
		assertEquals(100, Battery.refill(99, 100, 10_000, 100, 100), 0);
	}

	@Test
	public void uniqueRulesCheckSourceAndItemAndAllowOverrides()
	{
		Map<String, Map<String, Double>> drops = UniqueDrops.withOverrides(
			" zulrah | Magic Fang | 444;bad row;Kraken | Test drop | 100;Kraken | Invalid | Infinity");
		Map<String, Double> zulrah = UniqueDrops.forSource(drops, "Zulrah");
		Map<String, Double> kraken = UniqueDrops.forSource(drops, "Kraken");
		assertEquals(444, UniqueDrops.denominator(zulrah, "Magic fang"), 0);
		assertEquals(512, UniqueDrops.denominator(zulrah, "Tanzanite fang"), 0);
		assertEquals(0, UniqueDrops.denominator(UniqueDrops.forSource(drops, "Vorkath"), "Tanzanite fang"), 0);
		assertEquals(100, UniqueDrops.denominator(kraken, "Test drop"), 0);
		assertEquals(0, UniqueDrops.denominator(kraken, "Invalid"), 0);
		assertEquals(400, UniqueDrops.denominator(UniqueDrops.forSource(drops, "Reward pool (Tempoross)"), "Fish barrel"), 0);
		assertTrue(UniqueDrops.forSource(drops, "Cow").isEmpty());
	}

	@Test
	public void usesWikiTiersForBossesAndRaidThresholds()
	{
		assertEquals(BossingLadder.Tier.EASY, BossingLadder.npcTier("Scurrius", false));
		assertEquals(BossingLadder.Tier.ELITE, BossingLadder.npcTier("Vorkath", false));
		assertEquals(BossingLadder.Tier.MEDIUM, BossingLadder.npcTier("Kree'arra", false));
		assertEquals(BossingLadder.Tier.ELITE, BossingLadder.npcTier("Kree'arra", true));
		assertEquals(BossingLadder.Tier.ELITE, BossingLadder.tombsTier(299));
		assertEquals(BossingLadder.Tier.MASTER, BossingLadder.tombsTier(300));
		assertEquals(BossingLadder.Tier.MASTER, BossingLadder.tombsTier(499));
		assertEquals(BossingLadder.Tier.GRANDMASTER, BossingLadder.tombsTier(500));
	}
}

